export const averageCostDefinitions={
 purchaseAverage:{title:'Reconcile six equal cash purchases with fractional units and one fee per order',fields:[
  ['purchaseCash','Cash assigned to each monthly purchase, including its fee (CAD)',200,50,2000,50],
  ['purchaseFee','Fixed fee paid from each monthly cash amount (CAD)',2,0,25,1],
  ['quoteBase','First purchase price and price-pattern scale (CAD per unit)',20,5,100,5],
  ['quoteVariation','Variation of the authored six-price pattern (%)',100,0,150,10],
  ['valuationPrice','Separate valuation price after the sixth purchase (CAD per unit)',20,1,200,1]
 ]}
};
export function averageCostPlan(d){
 const pattern=[0,-.2,-.4,-.1,.2,0],net=d.purchaseCash-d.purchaseFee;let units=0,quoteSum=0;
 const rows=pattern.map((move,i)=>{
  const quote=d.quoteBase*(1+move*d.quoteVariation/100),bought=net/quote;units+=bought;quoteSum+=quote;
  return {x:i+1,quote,bought,units,securityCash:net*(i+1),fees:d.purchaseFee*(i+1),cash:d.purchaseCash*(i+1),arithmetic:quoteSum/(i+1),weighted:net*(i+1)/units,allIn:d.purchaseCash*(i+1)/units};
 });
 const end=rows.at(-1),marketValue=end.units*d.valuationPrice,priceChange=rows.reduce((s,r)=>s+r.bought*(d.valuationPrice-r.quote),0);
 return {rows,end,marketValue,priceChange,gain:marketValue-end.cash};
}
export function averageCostResult(kind,d){
 if(kind!=='purchaseAverage')throw Error('Unknown average-cost topic.');
 const p=averageCostPlan(d);
 return {metrics:[['Arithmetic average of the six execution prices',p.end.arithmetic,'money'],['Purchase-price amount divided by total units',p.end.weighted,'money'],['All household cash spent divided by total units',p.end.allIn,'money']],note:'Six original hypothetical monthly executions buy the same fictional asset with equal household cash each time. A fixed fee is paid from that cash before buying fractional units at the stated price. At 100% variation, prices are the selected base multiplied by 1, 0.8, 0.6, 0.9, 1.2 and 1; zero variation makes all six prices identical. Other variation settings scale only those authored deviations from the base. A separate valuation price is applied after purchase six. All three headline metrics are CAD per unit, not dollar balances or percentage returns. Fractional units are unrestricted and calculations retain precision. No dividends, splits, cash interest, spreads, price impact, currency changes, sale fees, tax, account limits or market forecasts are included. All-in cash per unit is an accounting comparison, not a determination of tax ACB. No lump-sum strategy, equal-unit strategy, annualized return or historical performance is calculated.',charts:[
  {id:'average-cost-price-record',type:'line',title:'The average execution price and the cash cost per unit answer different questions',unit:'money',unitLabel:'CAD per unit · cumulative averages through each purchase',tableUnit:'CAD per unit',xLabel:'Numbered monthly purchase',xMin:1,series:[{name:'Execution price at this purchase',rows:p.rows.map(r=>({x:r.x,value:r.quote}))},{name:'Cumulative arithmetic average execution price',dash:true,rows:p.rows.map(r=>({x:r.x,value:r.arithmetic}))},{name:'Cumulative purchase-price amount per unit',rows:p.rows.map(r=>({x:r.x,value:r.weighted}))},{name:'Cumulative household cash spent per unit, including fees',dash:true,rows:p.rows.map(r=>({x:r.x,value:r.allIn}))}],note:'The arithmetic-average line weights each execution price equally. The purchase-price average weights each price by the units acquired. The last line also includes fees paid from the same cash budget. The lines are cost records; none is a compound investment return or a guaranteed future selling price.'},
  {id:'average-cost-units',type:'bar',title:'Equal cash buys a different number of units at each execution',unit:'decimal',unitLabel:'Fractional units acquired at each monthly purchase',tableUnit:'Units',rows:p.rows.map(r=>({label:'Purchase '+r.x+' · CAD '+Number(r.quote.toFixed(2))+' per unit',value:r.bought})),note:'Units acquired equal the monthly cash amount less the fee, divided by that execution price. Lower prices buy more units when net purchase cash stays equal. Units are retained without rounding in the calculation; labels and table values round for display. Actual platforms may restrict fractional purchases.'},
  {id:'average-cost-value-bridge',type:'waterfall',title:'Reconcile household cash, fees and the separate valuation',unit:'money',rows:[{label:'Total household cash assigned to six purchases',value:p.end.cash},{label:'Fees paid from that cash before buying units',value:-p.end.fees},{label:'Change from execution prices to the valuation price',value:p.priceChange}],totalLabel:'Investment market value at the separate valuation',note:'Price change sums units from each purchase multiplied by valuation price minus that purchase’s execution price. Ending market value minus the original household cash is the unrealized cash gain or loss. This endpoint is not cash released by a sale; sale costs and tax are absent. Internal fee payments are deducted once.'},
  {id:'average-cost-mark-fee-matrix',type:'heatmap',title:'A purchase-price average below the arithmetic average does not guarantee a profit',unit:'money',signed:true,unitLabel:'CAD · unrealized market value minus total household cash; rows: valuation price; columns: fee per purchase',columns:[0,2,5,10].map(f=>'CAD '+f),rows:[.6,.8,1,1.2].map(multiple=>{const valuationPrice=d.quoteBase*multiple;return {label:'CAD '+Number(valuationPrice.toFixed(2)),values:[0,2,5,10].map(purchaseFee=>averageCostPlan({...d,purchaseFee,valuationPrice}).gain)};}),note:'Every cell retains the selected six execution prices and monthly cash amount. It replaces the fixed fee for every order and the final valuation price. These row prices are explicit multiples of the selected base, not estimated future ranges. Negative values remain visible. The valuation input affects the bridge; this matrix keeps its fixed comparison rows.'}
 ]};
}
